// 1. Input Validation Node
const body = $input.first().json.body || $input.first().json;

if (!body.title || !body.options || !Array.isArray(body.options) || body.options.length < 2) {
  throw new Error('Invalid input: Decision requires title and at least 2 options.');
}

if (!body.criteria || !Array.isArray(body.criteria) || body.criteria.length < 2) {
  throw new Error('Invalid input: Decision requires at least 2 evaluation criteria.');
}

return [{ json: body }];

// 2. Deterministic Scoring & Normalization Node
// Crucial rule: LLM never invents numerical scores.
const data = $input.first().json;
const options = data.options;
const criteria = data.criteria;
const rawWeights = data.weights || {};

// Calculate sum of weights
let totalWeight = 0;
for (const crit of criteria) {
  totalWeight += parseFloat(rawWeights[crit.key] || 0);
}

// Normalize to decimals summing to 1.0
const normalizedWeights = {};
for (const crit of criteria) {
  normalizedWeights[crit.key] = totalWeight > 0 ? (parseFloat(rawWeights[crit.key] || 0) / totalWeight) : (1 / criteria.length);
}

// Deterministic weighted score computation
const scores = options.map(opt => {
  let total = 0;
  const breakdown = {};
  for (const crit of criteria) {
    const val = parseFloat(opt.criteria[crit.key] || 0);
    const weight = normalizedWeights[crit.key];
    const contribution = val * weight;
    breakdown[crit.key] = Math.round(contribution * 100) / 100;
    total += contribution;
  }
  return {
    name: opt.name,
    score: Math.round(total * 10) / 10,
    breakdown,
    criteria: opt.criteria
  };
});

// Sort descending
scores.sort((a, b) => b.score - a.score);
scores.forEach((s, idx) => { s.rank = idx + 1; });

return [{
  json: {
    ...data,
    deterministicScores: scores,
    normalizedWeights,
    topOption: scores[0],
    runnerUp: scores[1] || null
  }
}];

// 3. Groq Prompt Constructor Node
const item = $input.first().json;

const systemPrompt = `You are an explainable decision-support AI within the Human-in-the-Loop Decision Intelligence Platform.
You are NOT the final decision-maker.
Analyze the provided decision data.
Identify the highest-scoring option based on the deterministic scores supplied.
Explain why that option is recommended using only the supplied evidence.
Identify important positive factors.
Identify negative factors and trade-offs.
Identify potential risks.
Provide one or more reasonable alternatives based on the supplied data.
Do not invent facts.
Do not create unsupported numerical values.
If data is missing, explicitly state that the evidence is insufficient.
The final human decision must remain separate from the AI recommendation.
Return ONLY valid structured JSON matching this schema:
{
  "recommendation": { "option": "...", "score": 87 },
  "confidence": 87,
  "summary": "...",
  "reasons": ["..."],
  "evidence": [{ "factor": "...", "value": 92, "impact": "positive|negative", "explanation": "..." }],
  "risks": [{ "risk": "...", "severity": "low|medium|high", "explanation": "..." }],
  "alternatives": [{ "option": "...", "score": 82, "reason": "..." }],
  "tradeoffs": ["..."]
}`;

const userPrompt = `Decision Context:
Title: ${item.title}
Description: ${item.description}
Category: ${item.category}
Options & Criteria: ${JSON.stringify(item.options, null, 2)}
Deterministic Calculated Scores: ${JSON.stringify(item.deterministicScores, null, 2)}`;

return [{
  json: {
    ...item,
    groqPayload: {
      model: process.env.GROQ_MODEL || 'llama-3.3-70b-versatile',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      response_format: { type: 'json_object' },
      temperature: 0.2
    }
  }
}];

// 4. Parse & Grounding Node
const groqResponse = $input.first().json;
const prevData = $('Deterministic Scoring').first().json;

let parsedAi = {};
try {
  const content = groqResponse.choices[0].message.content;
  parsedAi = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  parsedAi = {
    summary: 'AI analysis generated from deterministic calculations.',
    reasons: ['Highest weighted performance'],
    evidence: [],
    risks: [],
    alternatives: [],
    tradeoffs: []
  };
}

// Enforce that AI recommendation strictly adheres to deterministic top score
const topOption = prevData.topOption;
parsedAi.recommendation = {
  option: topOption.name,
  score: topOption.score
};

// 5. Analytical Confidence Calculation
// Formula: Completeness*30% + Separation*30% + Strength*20% + Coverage*20%
const completeness = 1.0;
const separation = prevData.runnerUp ? Math.min(1.0, Math.max(0.1, (topOption.score - prevData.runnerUp.score) / 15)) : 0.5;
const coverage = Math.min(1.0, Math.max(0.4, prevData.criteria.length / 5));
const strength = 0.85;

const rawConf = Math.round((completeness * 30) + (separation * 30) + (strength * 20) + (coverage * 20));
const calculatedConfidence = Math.min(96, Math.max(50, rawConf));

parsedAi.confidence = calculatedConfidence;
parsedAi.confidenceCategory = calculatedConfidence >= 80 ? 'High Confidence' : calculatedConfidence >= 60 ? 'Medium Confidence' : 'Low Confidence';
parsedAi.source = 'n8n_groq';

return [{
  json: {
    success: true,
    data: parsedAi,
    calculatedScores: prevData.deterministicScores
  }
}];
